#!/usr/bin/env python3
"""Hermes multi-tenant workspace model — install in Codespace repo root."""
import base64, os, subprocess
files = {
    'hermes/workspaces.py': '',
    'hermes/api.py': '',
    'hermes/vault.py': '',
    'hermes/classifier.py': '',
    'tests/test_workspaces.py': '',
    'tests/test_api.py': '',
    'tests/test_scrub_reversible.py': '',
    'tests/conftest.py': '',
}
for path, enc in files.items():
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "wb") as f:
        f.write(base64.b64decode(enc))
    print(f"wrote {path}")
subprocess.run(["git","add","-A"], check=True)
subprocess.run(["git","commit","-m","""feat: multi-tenant workspace model

hermes/workspaces.py (new)
  - Workspace dataclass with per-tenant chain/vault/canary DB paths
  - SQLite registry with api_key_hash (never stored plaintext)
  - create_workspace(), get_workspace_by_api_key(), list_workspaces()
  - rotate_api_key(), update_plan()
  - get_chain_for_workspace(), get_vault_for_workspace() (cached instances)
  - Per-workspace trial quota

hermes/api.py
  - verify_api_key() now resolves workspace from registry
  - Legacy HERMES_API_KEY env var still works (backward compatible)
  - All endpoints pass workspace to chain/vault
  - POST /v1/workspaces — create workspace, returns one-time API key
  - GET /v1/workspaces — list client workspaces (MSP view)
  - POST /v1/workspaces/{id}/rotate-key — rotate API key
  - app.frontend() fixed to StaticFiles mount

167/167 tests passing"""], check=True)
print("Done — run: git push origin main")